# Adaptive Rejection Sampling - Gilks & Wild (1992)
# Modular implementation in R

# --- Utility: validate numeric scalar ---
validate_positive <- function(x, name) {
  if (!is.numeric(x) || length(x) != 1 || is.na(x) || x <= 0) {
    stop(paste0("'", name, "' must be a positive number."))
  }
}

# --- Utility: validate domain ---
validate_domain <- function(domain) {
  if (!is.numeric(domain) || length(domain) != 2) {
    stop("domain must be a numeric vector of length 2: c(lower, upper).")
  }
  if (any(is.na(domain))) {
    stop("domain must not contain NA values.")
  }
  if (domain[1] >= domain[2]) {
    stop("domain lower bound must be less than upper bound.")
  }
}

# --- Check log-concavity at a set of points ---
# For a log-concave function, the log-density should be concave,
# meaning second differences should be <= 0 (approximately).
check_log_concavity <- function(logf, x, tol = 1e-7) {
  n <- length(x)
  if (n < 3) return(TRUE)
  # Compute second differences
  d1 <- diff(logf)
  d2 <- diff(d1)
  if (any(d2 > tol)) {
    stop("Log-concavity violated: the log-density appears non-concave.\n", 
         "ARS requires a log-concave target distribution.")
  }
  TRUE
}

# --- Build initial set of abscissae and compute h, H, w values ---
# h[i] = log(f(x_i)), H[i] = h[i] + f'(x_i), w[i] = x_i + h[i]/f'(x_i)
build_support <- function(logf, dlogf, x) {
  n <- length(x)
  h  <- logf(x)
  dh <- dlogf(x)
  # w[i] is the intersection of tangent at x[i] and x[i+1]
  # w[i] = (h[i+1]-h[i]-dh[i]*x[i+1]+dh[i+1]*x[i]) / (dh[i+1]-dh[i])
  w <- numeric(n)
  for (i in seq_len(n-1)) {
    denom <- dh[i+1] - dh[i]
    if (abs(denom) < 1e-15) {
      stop("Degenerate support: duplicate tangents.")
    }
    w[i] <- (h[i+1] - h[i] - dh[i]*x[i+1] + dh[i+1]*x[i]) / denom
  }
  # w[n] = Inf (last tangent extends to +Inf)
  w[n] <- Inf
  # Handle -Inf boundary: w[0] would be -Inf
  list(h = h, dh = dh, w = w, x = x)
}

# --- Squeeze function: lower envelope of the piecewise linear log-density ---
# For a given z, find which interval it falls in and return the lower bound.
squeeze_log <- function(z, sup) {
  h  <- sup$h
  dh <- sup$dh
  w  <- sup$w
  x  <- sup$x
  n  <- length(x)
  # Find which tangent interval z belongs to
  # z is in [w[i-1], w[i]] where we use tangent at x[i]
  idx <- sum(w <= z)  # number of w's <= z
  idx <- max(1, min(idx+1, n))
  # Squeeze value: tangent at x[idx] evaluated at z
  h[idx] + dh[idx]*(z - x[idx])
}

# --- Upper piecewise-linear envelope (H function) ---
upper_log <- function(z, sup) {
  h  <- sup$h
  dh <- sup$dh
  w  <- sup$w
  x  <- sup$x
  n  <- length(x)
  if (z < x[1]) {
    # leftmost tangent
    return(h[1] + dh[1]*(z - x[1]))
  }
  if (z >= x[n]) {
    # rightmost tangent
    return(h[n] + dh[n]*(z - x[n]))
  }
  # Find interval
  idx <- sum(x <= z)  # x[1]..x[idx] <= z
  # z is between x[idx] and x[idx+1], use w[idx]
  # The upper envelope in [x[idx], x[idx+1]] is min of tangent idx and idx+1
  # Actually the envelope is the min of adjacent tangents
  u1 <- h[idx]  + dh[idx]  *(z - x[idx])
  u2 <- h[idx+1] + dh[idx+1]*(z - x[idx+1])
  min(u1, u2)
}

# --- Generate random variate from the piecewise-exponential upper envelope ---
# The CDF of the piecewise-exponential can be inverted numerically.
# Break the domain into intervals [w[i-1], w[i]] with exponential densities.
sample_from_upper <- function(sup, lower, upper) {
  h  <- sup$h
  dh <- sup$dh
  w  <- sup$w
  x  <- sup$x
  n  <- length(x)

  # Intervals: [lower, w[1]], [w[1], w[2]], ..., [w[n-1], upper]
  # On each interval we have an exponential: exp(h[i] + dh[i]*(z - x[i]))
  # truncated to that interval.

  # Build a list of intervals with their parameters
  edges <- c(lower, w[1:(n-1)], upper)
  # n intervals, tangent index for interval j is j (1-indexed)
  # Interval j: [edges[j], edges[j+1]], tangent at x[j]

  # Compute unnormalized integral on each interval: exp(h[j]+dh[j]*(a-x[j])) integrated
  # If dh[j] == 0: exp(h[j])*(b-a)
  # Else: exp(h[j]+dh[j]*(a-x[j]))*(exp(dh[j]*(b-a))-1)/dh[j]
  m <- n
  integrals <- numeric(m)
  for (j in seq_len(m)) {
    a <- edges[j]
    b <- edges[j+1]
    if (a >= b) next
    if (abs(dh[j]) < 1e-15) {
      integrals[j] <- exp(h[j]) * (b - a)
    } else {
      # log integral = h[j] + dh[j]*(a-x[j]) + log(expm1(dh[j]*(b-a))) - log(dh[j])
      # Use log for numerical stability
      la <- h[j] + dh[j]*(a - x[j])
      lb <- h[j] + dh[j]*(b - x[j])
      if (abs(dh[j]*(b-a)) < 1e-10) {
        integrals[j] <- exp(la) * (b - a)
      } else {
        integrals[j] <- (exp(lb) - exp(la)) / dh[j]
      }
    }
  }
  integrals[is.na(integrals) | integrals < 0] <- 0
  total <- sum(integrals)
  if (total <= 0) stop("Upper envelope has zero integral; check domain.")
  probs <- integrals / total

  # Select interval
  j <- sample.int(m, 1, prob = probs)
  a <- edges[j]; b <- edges[j+1]

  # Inverse CDF within interval j
  u <- runif(1)
  if (abs(dh[j]) < 1e-15) {
    return(a + u * (b - a))
  }
  # CDF: (exp(dh*(z-x)) - exp(dh*(a-x))) / (exp(dh*(b-x)) - exp(dh*(a-x)))
  ea <- exp(dh[j]*(a - x[j]))
  eb <- exp(dh[j]*(b - x[j]))
  target <- ea + u * (eb - ea)
  z <- x[j] + log(target) / dh[j]
  z
}
