# --- Adaptive update: insert a new point into the support structure ---
# Maintains sorted x, h, dh, w arrays.
update_support <- function(sup, x_new, logf, dlogf) {
  h_new  <- logf(x_new)
  dh_new <- dlogf(x_new)
  x  <- sup$x
  h  <- sup$h
  dh <- sup$dh
  w  <- sup$w
  n  <- length(x)

  # Find insertion position
  if (is.infinite(x_new) || any(is.infinite(x))) {
    stop("Cannot insert infinite point into support.")
  }
  pos <- sum(x < x_new) + 1

  # Insert
  x  <- append(x,  x_new,  after = pos-1)
  h  <- append(h,  h_new,  after = pos-1)
  dh <- append(dh, dh_new, after = pos-1)

  # Recompute w at affected positions: pos-1, pos (now 1-indexed in new array)
  # w[i] = intersection of tangent at x[i] and x[i+1]
  # Need to recompute w for indices pos-1 and pos (if valid)
  n_new <- n + 1
  w_new <- numeric(n_new)
  w_new[n_new] <- Inf  # last is always Inf
  for (i in seq_len(n_new-1)) {
    denom <- dh[i+1] - dh[i]
    if (abs(denom) < 1e-15) {
      stop("Degenerate support after update: duplicate tangents.")
    }
    w_new[i] <- (h[i+1] - h[i] - dh[i]*x[i+1] + dh[i+1]*x[i]) / denom
  }
  list(h = h, dh = dh, w = w_new, x = x)
}

# --- Initial support construction ---
# Find initial points that bracket the mode and ensure proper tangents.
build_initial_support <- function(logf, dlogf, domain) {
  lower <- domain[1]
  upper <- domain[2]

  # Start with two interior points
  # We need points where the derivative is negative on the left
  # and positive on the right (to bracket the mode), or handle boundaries.

  x1 <- lower
  x2 <- upper
  if (is.infinite(lower) && is.infinite(upper)) {
    x1 <- -1; x2 <- 1
  } else if (is.infinite(lower)) {
    x1 <- x2 - 1; x2 <- x2 - 0.5
  } else if (is.infinite(upper)) {
    x1 <- lower + 0.5; x2 <- lower + 1
  }

  dh1 <- dlogf(x1)
  dh2 <- dlogf(x2)

  # Expand left if dh1 >= 0 (need negative derivative on left side)
  if (!is.infinite(lower)) {
    # If domain is bounded below, we can use the boundary
  } else {
    while (dh1 >= 0) {
      x1 <- x1 - 1
      dh1 <- dlogf(x1)
    }
  }

  # Expand right if dh2 <= 0 (need positive derivative on right side)
  if (!is.infinite(upper)) {
    # If domain is bounded above, we can use the boundary
  } else {
    while (dh2 <= 0) {
      x2 <- x2 + 1
      dh2 <- dlogf(x2)
    }
  }

  # Ensure x1 < x2
  if (x1 >= x2) {
    x1 <- x2 - 1
    dh1 <- dlogf(x1)
  }

  # Evaluate log-density
  h1 <- logf(x1)
  h2 <- logf(x2)
  if (!is.finite(h1) || !is.finite(h2)) {
    stop("Log-density is not finite at initial support points.\n", 
         "Try providing a more restrictive domain.")
  }

  # Check log-concavity on initial points
  x_init <- c(x1, x2)
  check_log_concavity(c(h1, h2), x_init)

  list(h = c(h1, h2), dh = c(dh1, dh2), x = x_init,
       w = Inf)
}
