# --- Main ARS function ---
ars <- function(density_function, domain, n = 1000) {
  # --- Input validation ---
  # n: sample count
  if (!is.numeric(n) || length(n) != 1 || is.na(n) || n < 1) {
    stop("n must be a positive integer.")
  }
  n <- as.integer(n)

  # domain: two-element vector
  validate_domain(domain)
  lower <- domain[1]
  upper <- domain[2]

  # density_function: must be a function
  if (!is.function(density_function)) {
    stop("density_function must be a function (vectorized).")
  }

  # Build log-density and its numerical derivative
  # logf(x) = log(density_function(x))
  logf <- function(x) {
    val <- density_function(x)
    if (any(val <= 0)) {
      # Log of zero is -Inf which is fine for ARS
      # But negative is not allowed
      if (any(val < 0)) {
        stop("density_function returned negative values.")
      }
      return(log(val))
    }
    log(val)
  }

  # Numerical derivative of log-density using central differences
  eps <- 1e-7
  dlogf <- function(x) {
    (logf(x + eps) - logf(x - eps)) / (2 * eps)
  }

  # Vectorized versions for support building
  logf_vec <- function(x) sapply(x, function(xi) logf(xi))
  dlogf_vec <- function(x) sapply(x, function(xi) dlogf(xi))

  # Check density at a test point
  test_pt <- if (is.finite(lower) && is.finite(upper)) (lower+upper)/2 else 0
  test_val <- logf(test_pt)
  if (is.na(test_val) || is.nan(test_val)) {
    stop("density_function returned NA/NaN at test point.")
  }

  # --- Build initial support ---
  sup <- build_initial_support(logf_vec, dlogf_vec, domain)

  # --- Sampling loop ---
  samples <- numeric(n)
  accepted <- 0
  attempts <- 0
  max_attempts <- n * 1000

  while (accepted < n && attempts < max_attempts) {
    attempts <- attempts + 1

    # Sample from upper envelope
    z <- sample_from_upper(sup, lower, upper)

    # Ensure z is within domain
    if (z < lower || z > upper) next

    # Evaluate log-density at z
    logf_z <- logf(z)

    # If log-density is not finite, reject
    if (!is.finite(logf_z)) next

    # Squeeze test: if u < exp(squeeze(z) - upper(z)), accept
    u <- log(runif(1))
    s_val <- squeeze_log(z, sup)
    u_val <- upper_log(z, sup)

    if (u < s_val - u_val) {
      # Accept without evaluating (already evaluated) — use squeeze
      accepted <- accepted + 1
      samples[accepted] <- z
      # Adaptive update: add z to support
      if (accepted < n) {
        tryCatch({
          sup <- update_support(sup, z, logf_vec, dlogf_vec)
          # Check log-concavity on current support
          check_log_concavity(sup$h, sup$x)
        }, error = function(e) {
          # If update fails (e.g., non-log-concave), stop with message
          stop(paste0("Log-concavity check failed during sampling: ", e$message))
        })
      }
    } else {
      # Squeeze test failed, do rejection test
      if (u < logf_z - u_val) {
        accepted <- accepted + 1
        samples[accepted] <- z
        # Adaptive update
        if (accepted < n) {
          tryCatch({
            sup <- update_support(sup, z, logf_vec, dlogf_vec)
            check_log_concavity(sup$h, sup$x)
          }, error = function(e) {
            stop(paste0("Log-concavity check failed during sampling: ", e$message))
          })
        }
      }
    }
  }

  if (accepted < n) {
    stop(paste0("Failed to collect ", n, " samples after ", attempts, " attempts.\n", 
                "The density may not be log-concave or the domain may be inappropriate."))
  }

  return(samples)
}
