# Adaptive Rejection Sampling - Gilks & Wild (1992)
# Modular implementation in R

# ===========================================================================
# Section 1: Validation and Utility Functions
# ===========================================================================

# Validate that domain is a valid 2-element numeric vector
validate_domain <- function(domain) {
  if (!is.numeric(domain) || length(domain) != 2) {
    stop("domain must be a numeric vector of length 2: c(lower, upper).")
  }
  if (any(is.na(domain))) {
    stop("domain must not contain NA values.")
  }
  if (domain[1] >= domain[2]) {
    stop("domain lower bound must be strictly less than upper bound.")
  }
}

# Check log-concavity: second differences of log-density must be <= 0
check_log_concavity <- function(logf_values, x_values, tol = 1e-7) {
  n <- length(x_values)
  if (n < 3) return(TRUE)
  # Sort by x if needed
  ord <- order(x_values)
  x_sorted <- x_values[ord]
  f_sorted <- logf_values[ord]
  # Second differences
  d1 <- diff(f_sorted)
  d2 <- diff(d1)
  if (any(d2 > tol)) {
    stop("Log-concavity violated: log-density is not concave.\n", 
         "ARS requires a log-concave target distribution.", call. = FALSE)
  }
  TRUE
}

# ===========================================================================
# Section 2: Support Structure Management
# ===========================================================================

# Build the initial support: find two points with valid derivative signs
build_initial_support <- function(logf, dlogf, lower, upper) {
  # Choose initial interior points
  if (is.finite(lower) && is.finite(upper)) {
    # Bounded domain: use points slightly inside
    range_w <- upper - lower
    x1 <- lower + 0.25 * range_w
    x2 <- lower + 0.75 * range_w
  } else if (is.finite(lower)) {
    # Bounded below, unbounded above: start near lower
    x1 <- lower + 0.5
    x2 <- lower + 1.0
  } else if (is.finite(upper)) {
    # Unbounded below, bounded above: start near upper
    x1 <- upper - 1.0
    x2 <- upper - 0.5
  } else {
    # Unbounded both sides
    x1 <- -1.0
    x2 <- 1.0
  }

  dh1 <- dlogf(x1)
  dh2 <- dlogf(x2)

  # For leftmost point: if domain extends to -Inf, need dh1 > 0
  # (so tangent decays as x -> -Inf)
  if (is.infinite(lower) && !is.na(dh1)) {
    max_iter <- 100
    iter <- 0
    while (dh1 <= 0 && iter < max_iter) {
      x1 <- x1 - max(1, abs(x1))
      dh1 <- dlogf(x1)
      iter <- iter + 1
    }
    if (dh1 <= 0) {
      stop("Cannot find a point with positive derivative on the left.\n",
           "Check that the density integrates to a finite value.", call. = FALSE)
    }
  }

  # For rightmost point: if domain extends to +Inf, need dh2 < 0
  # (so tangent decays as x -> +Inf)
  if (is.infinite(upper) && !is.na(dh2)) {
    max_iter <- 100
    iter <- 0
    while (dh2 >= 0 && iter < max_iter) {
      x2 <- x2 + max(1, abs(x2))
      dh2 <- dlogf(x2)
      iter <- iter + 1
    }
    if (dh2 >= 0) {
      stop("Cannot find a point with negative derivative on the right.\n",
           "Check that the density integrates to a finite value.", call. = FALSE)
    }
  }

  # Ensure x1 < x2
  if (x1 >= x2) {
    stop("Could not establish valid initial support points with x1 < x2.",
         call. = FALSE)
  }

  # Evaluate log-density at both points
  h1 <- logf(x1)
  h2 <- logf(x2)
  if (!is.finite(h1) || !is.finite(h2)) {
    stop("Log-density is not finite at initial support points.\n",
         "Try adjusting the domain to avoid zero-density regions.", call. = FALSE)
  }

  # Compute w[1] = intersection of tangents at x1 and x2
  denom <- dh2 - dh1
  if (abs(denom) < 1e-15) {
    stop("Degenerate support: tangents are parallel.", call. = FALSE)
  }
  w1 <- (h2 - h1 - dh1 * x2 + dh2 * x1) / denom

  list(x = c(x1, x2), h = c(h1, h2), dh = c(dh1, dh2), w = c(w1, Inf))
}

# Insert a new point into the support structure (maintaining sorted order)
update_support <- function(sup, x_new, logf, dlogf) {
  h_new  <- logf(x_new)
  dh_new <- dlogf(x_new)

  if (!is.finite(h_new)) return(sup)  # Skip if log-density is not finite

  x  <- sup$x
  h  <- sup$h
  dh <- sup$dh
  n  <- length(x)

  # Skip if point is too close to existing points
  if (any(abs(x - x_new) < 1e-12)) return(sup)

  # Find insertion position
  pos <- sum(x < x_new) + 1

  # Insert into arrays
  x  <- append(x,  x_new,  after = pos - 1)
  h  <- append(h,  h_new,  after = pos - 1)
  dh <- append(dh, dh_new, after = pos - 1)

  # Recompute all w values (intersection of consecutive tangents)
  n_new <- n + 1
  w_new <- numeric(n_new)
  w_new[n_new] <- Inf
  for (i in seq_len(n_new - 1)) {
    denom <- dh[i + 1] - dh[i]
    if (abs(denom) < 1e-15) {
      w_new[i] <- x[i] + 1  # Fallback for nearly parallel tangents
    } else {
      w_new[i] <- (h[i+1] - h[i] - dh[i]*x[i+1] + dh[i+1]*x[i]) / denom
    }
  }

  list(x = x, h = h, dh = dh, w = w_new)
}
