# ===========================================================================
# Section 5: Main ARS Function
# ===========================================================================
ars <- function(density_function, domain, n = 1000) {
  # --- Input validation ---
  if (!is.function(density_function)) {
    stop("density_function must be a function (vectorized).", call. = FALSE)
  }
  validate_domain(domain)
  if (!is.numeric(n) || length(n) != 1 || is.na(n) || n < 1 || n != as.integer(n)) {
    stop("n must be a positive integer.", call. = FALSE)
  }
  n <- as.integer(n)
  lower <- domain[1]; upper <- domain[2]

  # --- Define log-density and numerical derivative ---
  logf <- function(x) {
    val <- density_function(x)
    if (any(val < 0)) stop("density_function returned negative values.", call. = FALSE)
    log(val)
  }
  eps <- 1e-7
  dlogf <- function(x) {
    (logf(x + eps) - logf(x - eps)) / (2 * eps)
  }
  logf_vec  <- function(x) sapply(x, logf)
  dlogf_vec <- function(x) sapply(x, dlogf)

  # --- Build initial support ---
  sup <- build_initial_support(logf_vec, dlogf_vec, lower, upper)
  check_log_concavity(sup$h, sup$x)

  # --- Sampling loop ---
  samples  <- numeric(n)
  accepted <- 0L
  max_attempts <- n * 5000L
  attempts <- 0L

  while (accepted < n && attempts < max_attempts) {
    attempts <- attempts + 1L
    z <- sample_from_upper(sup, lower, upper)
    if (z < lower || z > upper) next

    logf_z <- logf(z)
    if (!is.finite(logf_z)) next

    u_log <- log(runif(1))
    h_val <- upper_log(z, sup)
    s_val <- squeeze_log(z, sup)

    accept <- FALSE
    if (u_log < s_val - h_val) {
      accept <- TRUE  # Squeeze test passed (no need to re-evaluate)
    } else if (u_log < logf_z - h_val) {
      accept <- TRUE  # Rejection test passed
    }

    if (accept) {
      accepted <- accepted + 1L
      samples[accepted] <- z
      # Adaptive update: insert z into support and re-check log-concavity
      if (accepted < n) {
        new_sup <- update_support(sup, z, logf_vec, dlogf_vec)
        tryCatch({
          check_log_concavity(new_sup$h, new_sup$x)
          sup <- new_sup
        }, error = function(e) {
          stop(paste0("Log-concavity check failed during sampling: ", e$message),
               call. = FALSE)
        })
      }
    }
  }

  if (accepted < n) {
    stop(sprintf("Failed to collect %d samples after %d attempts.\n",
                 n, attempts), call. = FALSE)
  }
  samples
}
