# =============================================================================
# Adaptive Rejection Sampling (Gilks & Wild, 1992)
# A modular R implementation for log-concave densities.
#
# Design: a small set of focused functions, each doing one discrete task:
#   validate_domain, check_log_concavity   -- input / property validation
#   build_initial_support, update_support  -- support-structure management
#   upper_log, squeeze_log                 -- the upper & lower envelopes
#   sample_from_upper, sample_linear       -- proposal samplers
#   ars                                     -- top-level driver
#   test                                    -- formal test suite
# =============================================================================

# --- Validate a two-point domain vector -------------------------------
validate_domain <- function(domain) {
  if (!is.numeric(domain) || length(domain) != 2) {
    stop("domain must be a numeric vector of length 2: c(lower, upper).", call. = FALSE)
  }
  if (any(is.na(domain))) {
    stop("domain must not contain NA values.", call. = FALSE)
  }
  if (domain[1] >= domain[2]) {
    stop("domain lower bound must be strictly less than the upper bound.", call. = FALSE)
  }
  invisible(NULL)
}

# --- Check that the log-density is concave (second differences <= 0) ---
check_log_concavity <- function(log_values, x_values, tol = 1e-6) {
  if (length(x_values) < 3) return(invisible(TRUE))
  ord  <- order(x_values)
  xv   <- x_values[ord]
  fv   <- log_values[ord]
  d2   <- diff(fv, lag = 2) - 2 * diff(fv, lag = 1)
  if (any(is.finite(d2) & d2 > tol)) {
    stop("Log-concavity violated: the log-density is not concave.\n",
         "Adaptive rejection sampling requires a log-concave target.", call. = FALSE)
  }
  invisible(TRUE)
}

# --- Test whether the log-density is (numerically) linear -------------
is_linear_logdensity <- function(dlogf, lower, upper) {
  if (is.finite(lower) && is.finite(upper)) {
    pts <- seq(lower + 0.1*(upper-lower), upper - 0.1*(upper-lower), length.out = 3)
  } else {
    pts <- c(-1, 0, 1)
  }
  s <- sapply(pts, dlogf)
  if (any(!is.finite(s))) return(FALSE)
  (max(s) - min(s)) < 1e-6
}

# --- Build the initial support: two points with usable derivative signs --
# For a log-concave f the slopes dlogf are non-increasing in x. We need the
# leftmost point's slope > 0 (if lower is -Inf) and the rightmost slope < 0
# (if upper is +Inf) so the envelope has finite integral.
build_initial_support <- function(logf, dlogf, lower, upper) {
  if (is.finite(lower) && is.finite(upper)) {
    rw <- upper - lower; x1 <- lower + 0.25*rw; x2 <- lower + 0.75*rw
  } else if (is.finite(lower)) {
    x1 <- lower + 0.5; x2 <- lower + 1.0
  } else if (is.finite(upper)) {
    x1 <- upper - 1.0; x2 <- upper - 0.5
  } else {
    x1 <- -1.0; x2 <- 1.0
  }
  dh1 <- dlogf(x1); dh2 <- dlogf(x2)

  # Expand left while slope is not positive (only if domain opens to -Inf)
  if (is.infinite(lower) && is.finite(dh1)) {
    for (i in 1:200) {
      if (dh1 > 0) break
      x1 <- x1 - max(1, abs(x1)); dh1 <- dlogf(x1)
    }
    if (dh1 <= 0) stop("Cannot bracket the left tail (density not integrable?).", call. = FALSE)
  }
  # Expand right while slope is not negative (only if domain opens to +Inf)
  if (is.infinite(upper) && is.finite(dh2)) {
    for (i in 1:200) {
      if (dh2 < 0) break
      x2 <- x2 + max(1, abs(x2)); dh2 <- dlogf(x2)
    }
    if (dh2 >= 0) stop("Cannot bracket the right tail (density not integrable?).", call. = FALSE)
  }

  if (x1 >= x2) stop("Could not establish two distinct initial points with x1 < x2.", call. = FALSE)

  h1 <- logf(x1); h2 <- logf(x2)
  if (!is.finite(h1) || !is.finite(h2)) {
    stop("Log-density is not finite at the initial support points.\n",
         "Adjust the domain to avoid zero-density regions.", call. = FALSE)
  }

  # Intersection w1 of the two tangents; fall back to midpoint for parallel
  # tangents (the linear / exponential case) where they never cross.
  denom <- dh2 - dh1
  if (abs(denom) < 1e-12) w1 <- 0.5 * (x1 + x2)
  else w1 <- (h2 - h1 - dh1*x2 + dh2*x1) / denom

  list(x = c(x1, x2), h = c(h1, h2), dh = c(dh1, dh2), w = c(w1, Inf))
}

# --- Insert an accepted point into the support (keeps x sorted) --------
update_support <- function(sup, x_new, logf, dlogf) {
  h_new  <- logf(x_new); dh_new <- dlogf(x_new)
  if (!is.finite(h_new)) return(sup)          # skip non-finite points
  x  <- sup$x; h <- sup$h; dh <- sup$dh; n <- length(x)
  if (any(abs(x - x_new) < 1e-12)) return(sup)  # avoid duplicates

  pos <- sum(x < x_new) + 1L
  x  <- append(x,  x_new,  after = pos - 1L)
  h  <- append(h,  h_new,  after = pos - 1L)
  dh <- append(dh, dh_new, after = pos - 1L)
  n_new <- n + 1L

  w_new <- numeric(n_new); w_new[n_new] <- Inf
  for (i in seq_len(n_new - 1L)) {
    denom <- dh[i + 1L] - dh[i]
    if (abs(denom) < 1e-12) w_new[i] <- 0.5 * (x[i] + x[i + 1L])
    else w_new[i] <- (h[i+1L] - h[i] - dh[i]*x[i+1L] + dh[i+1L]*x[i]) / denom
  }
  list(x = x, h = h, dh = dh, w = w_new)
}
