# --- Upper envelope H(z): piecewise-linear UPPER bound on log-density ----
# In each interval [w_{i-1}, w_i] the upper bound is the tangent at x_i.
upper_log <- function(z, sup) {
  x <- sup$x; h <- sup$h; dh <- sup$dh; w <- sup$w
  k <- length(x)
  if (k == 1L) return(h[1] + dh[1] * (z - x[1]))
  fw <- w[1:(k - 1L)]; fw <- fw[is.finite(fw)]
  i  <- min(max(sum(fw <= z) + 1L, 1L), k)
  h[i] + dh[i] * (z - x[i])
}

# --- Squeeze s(z): piecewise-linear LOWER bound using chords -----------
# Inside [x_i, x_{i+1}] the chord is a valid lower bound (log-concavity).
# Outside [x_1, x_k] we return -Inf to force a density evaluation.
squeeze_log <- function(z, sup) {
  x <- sup$x; h <- sup$h; k <- length(x)
  if (k < 2L || z < x[1] || z > x[k]) return(-Inf)
  i <- min(max(sum(x <= z), 1L), k - 1L)
  h[i] + (h[i + 1L] - h[i]) / (x[i + 1L] - x[i]) * (z - x[i])
}

# --- Sample z from the piecewise-exponential upper envelope ------------
sample_from_upper <- function(sup, lower, upper) {
  x <- sup$x; h <- sup$h; dh <- sup$dh; w <- sup$w
  k <- length(x)
  edges <- c(lower, w[1:(k - 1L)], upper)
  for (i in 2:k) if (is.infinite(edges[i])) edges[i] <- upper
  edges <- pmax(pmin(edges, upper), lower)
  for (i in 2:(k + 1L)) edges[i] <- max(edges[i], edges[i - 1L])

  integ <- numeric(k)
  for (j in seq_len(k)) {
    a <- edges[j]; b <- edges[j + 1L]
    if (a >= b) next
    if (abs(dh[j]) < 1e-15) integ[j] <- exp(h[j]) * (b - a)
    else {
      la <- h[j] + dh[j] * (a - x[j]); lb <- h[j] + dh[j] * (b - x[j])
      if (abs(dh[j] * (b - a)) < 1e-10) integ[j] <- exp(la) * (b - a)
      else integ[j] <- (exp(lb) - exp(la)) / dh[j]
    }
  }
  integ[is.na(integ) | is.infinite(integ) | integ < 0] <- 0
  tot <- sum(integ)
  if (!is.finite(tot) || tot <= 0) stop("Upper envelope has zero integral.", call. = FALSE)
  probs <- integ / tot

  j <- sample.int(k, 1L, prob = probs)
  a <- edges[j]; b <- edges[j + 1L]; u <- runif(1L)
  if (abs(dh[j]) < 1e-15) return(a + u * (b - a))
  ea <- exp(dh[j] * (a - x[j])); eb <- exp(dh[j] * (b - x[j]))
  if (abs(ea - eb) < 1e-30) return(a + u * (b - a))
  t <- ea + u * (eb - ea)
  if (!is.finite(t) || t <= 0) return(0.5 * (a + b))
  x[j] + log(t) / dh[j]
}

# --- Sample from a linear log-density (single exponential family) -------
# Target ~ exp(a + b*x) on [lower, upper]; inverse-CDF of the (truncated)
# exponential. Used when the log-density is linear (e.g. exponential target).
sample_linear <- function(slope, lower, upper) {
  if (abs(slope) < 1e-15) return(runif(1L, lower, upper))
  u <- runif(1L)
  eL <- exp(slope * lower); eU <- exp(slope * upper)
  eL + log(eL + u * (eU - eL)) / slope
}

# --- Top-level adaptive rejection sampler -------------------------------
ars <- function(density_function, domain, n = 1000) {
  # ---- input validation ----
  if (!is.function(density_function)) stop("density_function must be a function.", call. = FALSE)
  validate_domain(domain)
  if (!is.numeric(n) || length(n) != 1L || is.na(n) || n < 1 || n != as.integer(n)) {
    stop("n must be a positive integer.", call. = FALSE)
  }
  n <- as.integer(n)
  lower <- domain[1]; upper <- domain[2]

  # ---- log-density and its numerical derivative ----
  logf <- function(x) {
    val <- density_function(x)
    if (any(val < 0)) stop("density_function returned a negative value.", call. = FALSE)
    log(val)
  }
  eps <- 1e-7
  dlogf <- function(x) (logf(x + eps) - logf(x - eps)) / (2 * eps)
  logf_vec  <- function(x) sapply(x, logf)
  dlogf_vec <- function(x) sapply(x, dlogf)

  # detect linear log-density (exact proposal via sample_linear)
  linear <- is_linear_logdensity(dlogf, lower, upper)

  # ---- build & verify initial support ----
  sup <- build_initial_support(logf_vec, dlogf_vec, lower, upper)
  check_log_concavity(sup$h, sup$x)

  # ---- rejection loop ----
  samples <- numeric(n); accepted <- 0L
  max_attempts <- n * 5000L; attempts <- 0L
  while (accepted < n && attempts < max_attempts) {
    attempts <- attempts + 1L
    z <- if (linear) sample_linear(dlogf(0.5*(lower+upper) if is.finite(lower)+is.finite(upper) else 0), lower, upper)
        else sample_from_upper(sup, lower, upper)
    if (z < lower || z > upper) next

    logf_z <- logf(z)
    if (!is.finite(logf_z)) next
    u_log <- log(runif(1L))
    h_val <- upper_log(z, sup); s_val <- squeeze_log(z, sup)

    if (u_log < s_val - h_val || u_log < logf_z - h_val) {
      accepted <- accepted + 1L; samples[accepted] <- z
      if (accepted < n) {                      # adapt: insert & re-check
        ns <- update_support(sup, z, logf_vec, dlogf_vec)
        tryCatch({ check_log_concavity(ns$h, ns$x); sup <- ns },
                 error = function(e) stop("Log-concavity check failed during sampling: ", e$message, call. = FALSE))
      }
    }
  }
  if (accepted < n) stop(sprintf("Could not collect %d samples in %d attempts (non-log-concave?).", n, attempts), call. = FALSE)
  samples
}
